import hashlib,json,pathlib,struct,subprocess
binary=pathlib.Path("/nix/store/67xf635fy5p8pryn15rwfc5iz63gk0kx-hello-2.12.3/bin/hello")
raw=binary.read_bytes()
header={"magic":raw[:4].hex(),"class":raw[4],"endianness":raw[5],"machine":struct.unpack("<H",raw[18:20])[0],"sha256":hashlib.sha256(raw).hexdigest()}
if raw[:4]!=b"\x7fELF" or raw[4]!=2 or raw[5]!=1 or header["machine"]!=183:
    raise SystemExit("expected a little-endian ELF64 AArch64 executable")
version=subprocess.run(["qemu-aarch64","--version"],capture_output=True,text=True,check=True).stdout.splitlines()[0]
result=subprocess.run(["qemu-aarch64",str(binary)],capture_output=True,text=True,timeout=20)
record={"binary":str(binary),"elf":header,"qemu_version":version,"execution":{"command":["qemu-aarch64",str(binary)],"exit_code":result.returncode,"stdout":result.stdout,"stderr":result.stderr},"scope":"AArch64 userspace ABI under explicit QEMU; no tablet boot or GPU test"}
pathlib.Path("/work/nix-hello-qemu-result.json").write_text(json.dumps(record,indent=2)+"\n")
print(json.dumps(record,indent=2))
if result.returncode or result.stdout!="Hello, world!\n":
    raise SystemExit(1)

